    const out = [];
    for (let t = first; t <= last + 3600; t += step) { if (t > now) break; out.push({ t, kept: 0, n: 0, worker: 0 }); }
    if (!out.length) out.push({ t: last, kept: 0, n: 0, worker: 0 });
