    const tip = el("div", { class: "tip", "aria-hidden": "true" });
    const labelEvery = Math.max(1, Math.ceil(out.length / Math.max(2, Math.floor((W - L - R) / 110))));
    // labels counted back from the newest bucket, so "now" is always labelled
